function alerts(e){const d=e.details||{},s=e.sy,a=[];
if(s.includes('ret'))a.push(L('Retensi urin: tidak bisa berkemih dapat memerlukan evaluasi medis segera.|Urinary retention: inability to urinate may need urgent medical evaluation.'));
if(s.includes('sp')&&d.sp?.onset=='sudden'&&+d.sp?.pain>=7)a.push(L('Nyeri skrotum mendadak dan berat: segera cari evaluasi medis/IGD.|Sudden severe scrotal pain: seek urgent medical care/ER now.'));
if(s.includes('flank')&&(s.includes('fev')||d.flank?.fever=='y'))a.push(L('Demam disertai nyeri pinggang: segera periksakan diri ke tenaga kesehatan.|Fever with flank pain: see a healthcare professional promptly.'));
if(s.includes('hem')&&(d.hem?.clot=='y'||d.hem?.color=='dark'||e.sev>=8))a.push(L('Hematuria yang berat/mengkhawatirkan: segera cari evaluasi medis.|Heavy or concerning hematuria: seek medical evaluation promptly.'));
return a}
const alertHtml=a=>a.map(x=>`<div class=alert>⚠ ${x}<br><small>${L('Ini bukan diagnosis. Segera hubungi dokter/IGD.|This is not a diagnosis. Contact a doctor/ER promptly.')}</small></div>`).join('');
